/**
 * App-local bearer-token auth for the per-device IoT ingest paths.
 *
 * Physical IoT devices POST heartbeat, telemetry, command-ack/complete, and
 * log-write requests with `Authorization: Bearer <token>`. The token is a
 * 32-char base64url string generated by `POST /api/iot-devices/:id/tokens`
 * and shown to the user ONCE; only its SHA-256 hex digest is persisted in
 * `device_tokens.token_hash`.
 *
 * Verification:
 *   1. Look up the row by `token_hash` (single-row indexed lookup).
 *   2. Compare digests via `crypto.timingSafeEqual` to defeat timing oracles.
 *   3. Reject if `enabled = false` or `revoked_at IS NOT NULL`.
 *   4. Stash `device_id` + `owner_id` on `res.locals.deviceAuth` so handlers
 *      can persist with the correct ownership without trusting a body-supplied
 *      `device_id`.
 *
 * Mirrors the per-meter pattern from `energy-monitoring`. **Not** a candidate
 * for the molecule bond system — this is normal app-level resource auth,
 * scoped to the IoT ingest endpoints (HTTP-only in v1; MQTT bond is deferred
 * per INVENTORY).
 *
 * @module
 */
import { createHash, randomBytes, timingSafeEqual } from 'node:crypto'

import type { NextFunction, Request, RequestHandler, Response } from 'express'

import { findMany, updateById } from '@molecule/api-database'
import { t } from '@molecule/api-i18n'

const TOKEN_BYTES = 24 // base64url(24) → 32 chars
const TOKEN_HASH_HEX_LEN = 64 // sha256 hex digest length

/** Random 32-char base64url string. Kept small enough to fit in a device's flash config. */
export function generateDeviceToken(): string {
  return randomBytes(TOKEN_BYTES).toString('base64url')
}

/** SHA-256 hex digest of a plaintext token, used for both lookup and comparison. */
export function hashDeviceToken(plaintext: string): string {
  return createHash('sha256').update(plaintext).digest('hex')
}

/** Constant-time comparison of two hex digests of the same length. */
function safeHexEq(a: string, b: string): boolean {
  if (a.length !== b.length || a.length !== TOKEN_HASH_HEX_LEN) return false
  try {
    return timingSafeEqual(Buffer.from(a, 'hex'), Buffer.from(b, 'hex'))
  } catch (_error) {
    // Buffer conversion failed (invalid hex); treat as not-equal
    return false
  }
}

export interface DeviceAuthLocals {
  deviceId: string
  ownerId: string
  tokenId: string
}

declare module 'express-serve-static-core' {
  interface Locals {
    deviceAuth?: DeviceAuthLocals
  }
}

/**
 * Express middleware. Reads `Authorization: Bearer <token>`; on success,
 * sets `res.locals.deviceAuth = { deviceId, ownerId, tokenId }` and calls next().
 * On any failure, responds 401 (no body leak about which step failed).
 */
export const requireDeviceToken: RequestHandler = async (
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  const header = req.headers.authorization
  if (!header || !header.startsWith('Bearer ')) {
    res.status(401).json({
      error: t('devices.invalidToken', undefined, { defaultValue: 'Invalid device token.' }),
    })
    return
  }
  const token = header.slice('Bearer '.length).trim()
  if (token.length === 0) {
    res.status(401).json({
      error: t('devices.invalidToken', undefined, { defaultValue: 'Invalid device token.' }),
    })
    return
  }

  const candidateHash = hashDeviceToken(token)
  try {
    const rows = await findMany<{
      id: string
      device_id: string
      owner_id: string
      token_hash: string
      enabled: boolean
      revoked_at: Date | null
    }>('device_tokens', {
      where: [{ field: 'token_hash', operator: '=', value: candidateHash }],
      limit: 1,
    })
    const row = rows[0]
    if (!row || !row.enabled || row.revoked_at) {
      res.status(401).json({
        error: t('devices.invalidToken', undefined, { defaultValue: 'Invalid device token.' }),
      })
      return
    }
    if (!safeHexEq(row.token_hash, candidateHash)) {
      res.status(401).json({
        error: t('devices.invalidToken', undefined, { defaultValue: 'Invalid device token.' }),
      })
      return
    }

    res.locals.deviceAuth = {
      deviceId: row.device_id,
      ownerId: row.owner_id,
      tokenId: row.id,
    }

    // Synthesise a session so downstream middleware that reads
    // `res.locals.session.userId` (e.g. `enforceLimit` from
    // `@molecule/api-entitlements`) accepts the request. Semantically the
    // device is acting on behalf of its owner — telemetry/commands count
    // against the owner's tier quota, not against an anonymous identity.
    const existingSession = (res.locals.session as { userId?: string } | undefined) ?? {}
    res.locals.session = { ...existingSession, userId: row.owner_id }

    // Best-effort last-used stamp; failure here must not block ingest.
    try {
      await updateById('device_tokens', row.id, { last_used_at: new Date() })
    } catch (_error) {
      /* last-used stamp is best-effort; authentication already succeeded */
    }
    next()
  } catch (_error) {
    res.status(401).json({
      error: t('devices.invalidToken', undefined, { defaultValue: 'Invalid device token.' }),
    })
  }
}
